using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.FiniteGroups.GroupAlgebra;

internal sealed class PGroupAugmentationDocument : IScribeDocumentDefinition
{
    private static readonly LibraryNoteRef Webb =
        LibraryNoteRef.Create("D5/L/FiniteGroups/webb2016pgroups");

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Central group quotients control whole powers of modular augmentation ideals.",
        H("Augmentation Ideals of Finite p-Groups"),
        Blocks(Describe.Lean(
            DescribeId.Create("p-group-augmentation-cardinal-bound"),
            DeclarationHandle.Create("D5/S3/FiniteGroups/GroupAlgebra/PGroupAugmentation.augmentation_ideal_pow_card"),
            H("The group order bounds the nilpotence index"),
            StatementSource.FromLean(),
            AssessedProvenance.FromLiterature(Webb),
            Blocks(
                Paragraph(Text("Let p be prime, R any commutative ring of characteristic p, and G any finite p-group. The standard augmentation sends every group basis element to one. Its actual kernel I, regarded as a two-sided ideal in the possibly noncommutative group algebra R[G], satisfies I raised to the cardinality of G equals zero. The trivial group is included with exponent one. No finiteness or field assumption is imposed on R.")),
                Paragraph(Text("Choose a central element z of order p. For C generated by z, the kernel of R[G] to R[G/C] is the principal ideal J generated by z minus one. To prove the reverse kernel inclusion, quotient by J, factor the group homomorphism through G/C, and extend it to the group algebra. This constructs a left inverse after taking the ideal quotient and avoids a transversal.")),
                Paragraph(Text("Induction on the group order transports the entire power I raised to the cardinality of G/C into J. Centrality makes J two-sided, and the commuting characteristic-p identity gives J raised to p equals zero. The identity cardinality of G equals p times cardinality of G/C yields the claimed bound. This is a classical modular representation theory method, not a literature novelty claim. Webb Chapter 6, Exercises 15–17 supply the quotient-kernel and direct nilpotence route; Proposition 6.3.3(3) states qualitative field-coefficient nilpotence. The displayed cardinal bound and arbitrary commutative coefficients are the precise formal scope here."))),
            DescribeRole.Theorem))));
}
